#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="2.4.22"
INSTALLER_REV="PREMARKET-RERANK-SLOT-STABLE-V2"
APP_VERSION="NOVA-2.4.22"
ZIP_NAME="QUANT_NOVA_2.4.22_PREMARKET_RERANK_SLOT_STABLE_V2.zip"
ROOT_NAME="nova2422"
EXPECTED_ZIP_SHA256="9a6c4b22a53dda8cec2b087e58754951b7fd139fcec84c98918c97fabc16435b"
APP_DIR="$HOME/quant-nova"
IMAGE="quant-nova:2.4.22"
CONTAINER="quant-nova"
NETWORK="kiwoom-net"
HOST_PORT="3200"
umask 077
TMP="$(mktemp -d)"
STAMP="$(date +%Y%m%d%H%M%S)"
BACKUP="${CONTAINER}-backup-${STAMP}"
DEPLOY_START_EPOCH="$(date +%s)"
OLD_RENAMED=0
NEW_STARTED=0
SUCCESS=0

cleanup(){
  [[ -n "${TMP:-}" && -d "$TMP" ]] || return 0
  chmod -R u+rwX "$TMP" >/dev/null 2>&1 || sudo chmod -R u+rwX "$TMP" >/dev/null 2>&1 || true
  rm -rf "$TMP" >/dev/null 2>&1 || sudo rm -rf "$TMP" >/dev/null 2>&1 || true
}
say(){ printf '\n==> %s\n' "$*"; }
rollback(){
  local ec=$?
  [[ $ec -eq 0 || $SUCCESS -eq 1 ]] && return 0
  echo "[자동복구] NOVA $VERSION 적용 실패 — 이전 컨테이너 복구" >&2
  mkdir -p "$APP_DIR/deployments" >/dev/null 2>&1 || true
  local faildiag="$APP_DIR/deployments/NOVA-${VERSION}-${STAMP}-FAILED.diag"
  {
    echo "status=FAILED"
    echo "version=NOVA-${VERSION}"
    echo "installer_rev=$INSTALLER_REV"
    echo "failed_at=$(date -Is)"
    echo "exit_code=$ec"
    echo "--- docker ps -a ---"
    sudo docker ps -a --filter name="^/${CONTAINER}$" --format 'name={{.Names}} image={{.Image}} status={{.Status}} ports={{.Ports}}' 2>&1 || true
    echo "--- inspect ---"
    sudo docker inspect "$CONTAINER" --format 'status={{.State.Status}} exit={{.State.ExitCode}} error={{.State.Error}} image={{.Config.Image}}' 2>&1 || true
    echo "--- logs tail 400 ---"
    sudo docker logs --tail 400 "$CONTAINER" 2>&1 || true
  } > "$faildiag" 2>&1 || true
  echo "FAIL_DIAG=$faildiag" >&2
  if [[ $OLD_RENAMED -eq 1 ]]; then
    sudo docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
  elif [[ $NEW_STARTED -eq 1 ]]; then
    sudo docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
  fi
}
trap cleanup EXIT
trap rollback ERR

[[ "$(id -u)" -ne 0 ]] || { echo "ubuntu 사용자로 실행하세요." >&2; exit 1; }
echo "=== START QUANT NOVA 2.4.22 CLOSE ENERGY + OPENING SHAKEOUT REVERSAL [$INSTALLER_REV] ==="

say "1/7 사전점검 + 기존 Key/Secret/데이터 보존"
for c in python3 node curl sha256sum base64 awk df; do command -v "$c" >/dev/null 2>&1 || { echo "필수 명령 없음: $c" >&2; exit 1; }; done
sudo docker info >/dev/null 2>&1 || { echo "Docker daemon 접근 실패" >&2; exit 1; }
FREE_KB="$(df -Pk "$HOME" | awk 'NR==2{print $4}')"
[[ ${FREE_KB:-0} -ge 1048576 ]] || { echo "디스크 여유 1GB 미만" >&2; exit 1; }
OWNER_ID_PRE="$(sudo docker ps -q --filter publish=${HOST_PORT} | head -n1 || true)"
if [[ -n "$OWNER_ID_PRE" ]]; then
  OWNER_NAME_PRE="$(sudo docker inspect "$OWNER_ID_PRE" --format '{{.Name}}' | sed 's#^/##')"
  [[ "$OWNER_NAME_PRE" == "$CONTAINER" ]] || { echo "포트 $HOST_PORT 사용 중: $OWNER_NAME_PRE" >&2; exit 1; }
fi
[[ -s "$APP_DIR/.env" ]] || { echo "$APP_DIR/.env 없음" >&2; exit 1; }
KEYLEN="$(sed -n 's/^KIWOOM_APP_KEY=//p' "$APP_DIR/.env" | tail -n1 | awk '{print length}')"
SECLEN="$(sed -n -e 's/^KIWOOM_APP_SECRET=//p' -e 's/^KIWOOM_SECRET_KEY=//p' "$APP_DIR/.env" | tail -n1 | awk '{print length}')"
[[ ${KEYLEN:-0} -gt 5 && ${SECLEN:-0} -gt 5 ]] || { echo "Key/Secret 확인 실패" >&2; exit 1; }
mkdir -p "$APP_DIR/data" "$APP_DIR/deployments"; chmod 700 "$APP_DIR/data"
ACCESS_TOKEN_VALUE="$(sed -n 's/^APP_ACCESS_TOKEN=//p' "$APP_DIR/.env" | tail -n1)"
if [[ -z "$ACCESS_TOKEN_VALUE" ]]; then
  ACCESS_TOKEN_VALUE="$(python3 -c 'import secrets; print(secrets.token_urlsafe(32))')"
  printf '\nAPP_ACCESS_TOKEN=%s\n' "$ACCESS_TOKEN_VALUE" >> "$APP_DIR/.env"
  chmod 600 "$APP_DIR/.env"
fi
echo "KEY_SECRET=OK (values hidden)"
echo "DATA_DIR=$APP_DIR/data"

say "2/7 내장 원본 복원 + ZIP SHA + SOURCE_MANIFEST"
base64 -d > "$TMP/$ZIP_NAME" <<'NOVA_2422_ZIP_PAYLOAD'
