ACTUAL_SHA="$(sha256sum "$TMP/$ZIP_NAME" | awk '{print $1}')"
[[ "$ACTUAL_SHA" == "$EXPECTED_ZIP_SHA256" ]] || { echo "ZIP SHA 불일치" >&2; exit 1; }
echo "ZIP_SHA256=OK $ACTUAL_SHA"
# Extract with Python zipfile instead of `unzip` so hostile/broken Unix mode bits stored
# in the ZIP cannot create non-traversable directories. The private temp tree is
# created by the current user under umask 077; we then normalize modes top-down.
mkdir -p "$TMP/src"
python3 - "$TMP/$ZIP_NAME" "$TMP/src" "$ROOT_NAME" <<'PYZIPSAFE'
import os, sys, stat, zipfile
from pathlib import Path
zip_path=Path(sys.argv[1])
dest=Path(sys.argv[2]).resolve()
root_name=sys.argv[3].rstrip('/')
with zipfile.ZipFile(zip_path) as z:
    names=z.namelist()
    if not names or not all(n == root_name or n.startswith(root_name + '/') for n in names):
        raise SystemExit('ZIP root contract violation')
    for info in z.infolist():
        # Zip Slip guard: reject absolute paths, parent traversal, and symlinks.
        p=Path(info.filename)
        if p.is_absolute() or '..' in p.parts:
            raise SystemExit(f'unsafe ZIP path: {info.filename}')
        unix_mode=(info.external_attr >> 16) & 0xFFFF
        if stat.S_ISLNK(unix_mode):
            raise SystemExit(f'symlink not allowed in ZIP: {info.filename}')
    z.extractall(dest)
root=dest/root_name
if not root.is_dir():
    raise SystemExit(f'ZIP root missing: {root_name}')
# os.walk(topdown=True) can traverse because Python-created directories use umask-safe
# permissions rather than the ZIP's stored mode bits. Normalize deterministically.
for cur, dirs, files in os.walk(root, topdown=True, followlinks=False):
    os.chmod(cur, 0o700)
    for d in dirs:
        dp=Path(cur)/d
        if dp.is_symlink(): raise SystemExit(f'symlink dir not allowed: {dp}')
        os.chmod(dp, 0o700)
    for f in files:
        fp=Path(cur)/f
        if fp.is_symlink(): raise SystemExit(f'symlink file not allowed: {fp}')
        os.chmod(fp, 0o600)
print('PYTHON_ZIP_EXTRACT=PASS')
PYZIPSAFE
ROOT="$TMP/src/$ROOT_NAME"
CURRENT_UID="$(id -u)"
# Verify ownership and actual readability/traversability; PASS is never just a print.
BAD_OWNER="$(find "$ROOT" -xdev ! -uid "$CURRENT_UID" -print -quit)"
[[ -z "$BAD_OWNER" ]] || { echo "임시 소스 트리에 비정상 소유권 감지: $BAD_OWNER" >&2; exit 1; }
[[ -r "$ROOT/SOURCE_MANIFEST.sha256" && -x "$ROOT" && -x "$ROOT/app" && -r "$ROOT/app/main.py" ]] || { echo "임시 소스 권한 정상화 실패" >&2; exit 1; }
# Real read/write/delete probe inside the tree.
PROBE="$ROOT/.permission_probe.$$"
printf 'permission-probe\n' > "$PROBE"
[[ -r "$PROBE" && -w "$PROBE" ]] || { echo "임시 소스 RW probe 실패" >&2; exit 1; }
rm -f "$PROBE"
[[ ! -e "$PROBE" ]] || { echo "임시 소스 delete probe 실패" >&2; exit 1; }
echo "SOURCE_TREE_PERMISSION=PASS owner_uid=$CURRENT_UID dirs=700 files=600 rw_delete_probe=PASS"
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null) || { echo "SOURCE_MANIFEST 불일치" >&2; exit 1; }
echo "SOURCE_MANIFEST=PASS"

say "3/7 공식 계약/회귀 정적검증 (selfcheck는 Docker 의존성 설치 후 실행)"
python3 -m py_compile "$ROOT/app/main.py" "$ROOT/app/evidence_engine.py" "$ROOT/app/archive_engine.py" "$ROOT/app/shadow_engine.py" "$ROOT/app/rs_shadow_engine.py" "$ROOT/scripts/replay_backtest.py"
node --check "$ROOT/static/nova.js" >/dev/null
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null)
python3 - "$ROOT" <<'PYDEPGUARD'
