# R16 liveness soak: post-close review tasks become eligible within seconds after startup.
# Require the SAME host->container path used by the UI to remain responsive repeatedly.
echo 'HTTP_LIVENESS_SOAK=START probes=12 interval=2s max_time=3s retries=3'
R16_LAT_FILE="$TMP/r16_health_latency.txt"; : > "$R16_LAT_FILE"
for i in $(seq 1 12); do
  probe_file="$TMP/r16_health_$i.json"
  T=""
  for attempt in 1 2 3; do
    rm -f "$probe_file"
    if T="$(curl -fsS --connect-timeout 1 --max-time 3 -o "$probe_file" -w '%{time_total}' "http://127.0.0.1:${HOST_PORT}/api/health" 2>/dev/null)" && [[ -s "$probe_file" ]]; then
      break
    fi
    T=""
    sleep 1
  done
  [[ -n "$T" && -s "$probe_file" ]] || { echo "HTTP_LIVENESS_SOAK=FAIL probe=$i no_valid_body_after_3_attempts" >&2; exit 1; }
  python3 - "$probe_file" "$T" <<'PYR16PROBE'
import json,sys
h=json.load(open(sys.argv[1])); t=float(sys.argv[2])
assert h.get('ok') is True and h.get('version')=='NOVA-2.4.22'
assert t < 3.0, t
print(f'HTTP_HEALTH_PROBE=PASS time={t:.3f}s')
PYR16PROBE
  printf '%s\n' "$T" >> "$R16_LAT_FILE"
  sleep 2
done
python3 - "$R16_LAT_FILE" <<'PYR16LAT'
import sys,statistics
x=[float(v.strip()) for v in open(sys.argv[1]) if v.strip()]
x.sort(); p95=x[min(len(x)-1,max(0,int(len(x)*.95)-1))]
assert len(x)==12 and max(x)<3.0
print(f'HTTP_LIVENESS_SOAK=PASS probes={len(x)} max={max(x):.3f}s median={statistics.median(x):.3f}s p95={p95:.3f}s')
PYR16LAT

api_get() {
  local endpoint="$1" timeout="${2:-12}" tries="${3:-4}" body="" i
  for i in $(seq 1 "$tries"); do
    body="$(curl -fsS --connect-timeout 2 --max-time "$timeout" "http://127.0.0.1:${HOST_PORT}${endpoint}" 2>/dev/null || true)"
    if [[ -n "$body" ]] && printf '%s' "$body" | python3 -c 'import sys,json; json.load(sys.stdin)' >/dev/null 2>&1; then
      printf '%s' "$body"
      return 0
    fi
    sleep 2
  done
  return 1
}

